import os, re, json, math, gc, random, time
import numpy as np
import torch
from transformers import AutoTokenizer, AutoModelForCausalLM

working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

MODEL_DIR = "/data/zhenqian/models"
MODEL_PATH = os.path.join(MODEL_DIR, "DeepSeek-R1-Distill-Llama-8B")
if not os.path.isdir(MODEL_PATH):
    # try common alternatives
    for name in os.listdir(MODEL_DIR) if os.path.isdir(MODEL_DIR) else []:
        if "R1-Distill-Llama-8B" in name:
            MODEL_PATH = os.path.join(MODEL_DIR, name)
            break
print("Loading model from", MODEL_PATH)

tokenizer = AutoTokenizer.from_pretrained(
    MODEL_PATH, local_files_only=True, trust_remote_code=True
)
model = AutoModelForCausalLM.from_pretrained(
    MODEL_PATH,
    local_files_only=True,
    trust_remote_code=True,
    torch_dtype=torch.bfloat16 if torch.cuda.is_available() else torch.float32,
    device_map="auto",
)
model.eval()
if tokenizer.pad_token_id is None:
    tokenizer.pad_token = tokenizer.eos_token


# --- Build a small reasoning task set (arithmetic word problems with known integer answers) ---
def make_tasks(n=40, seed=0):
    rng = random.Random(seed)
    tasks = []
    for i in range(n):
        cat = i % 4
        if cat == 0:
            a, b, c = rng.randint(12, 99), rng.randint(12, 99), rng.randint(2, 9)
            q = f"A store has {a} apples. It receives {b} more and then sells {c} boxes of 5 apples each. How many apples remain?"
            ans = a + b - c * 5
        elif cat == 1:
            a, b = rng.randint(3, 12), rng.randint(3, 12)
            q = f"A rectangle has length {a} and width {b}. What is its perimeter?"
            ans = 2 * (a + b)
        elif cat == 2:
            a, b, c = rng.randint(2, 9), rng.randint(2, 9), rng.randint(2, 9)
            q = f"Compute {a} * {b} + {c}."
            ans = a * b + c
        else:
            a, b = rng.randint(20, 80), rng.randint(2, 9)
            q = f"If a train travels {a} miles in {b} hours, what is its speed in miles per hour (rounded to nearest integer)?"
            ans = round(a / b)
        tasks.append({"id": i, "category": cat, "question": q, "answer": ans})
    return tasks


tasks = make_tasks(40)
print(f"Built {len(tasks)} tasks")

# --- Behaviour regex patterns ---
BEHAVIOURS = {
    "hedging": re.compile(
        r"\b(maybe|perhaps|i think|might be|not sure|possibly|likely|uncertain|i'm not sure|could be)\b",
        re.I,
    ),
    "example_generation": re.compile(
        r"\b(for example|for instance|let's try|let me try|suppose|consider the case|test with|plug in)\b",
        re.I,
    ),
    "backtracking": re.compile(
        r"\b(wait|hold on|actually|on second thought|let me reconsider|hmm,? no|scratch that)\b",
        re.I,
    ),
    "self_correction": re.compile(
        r"\b(let me check|double.?check|recalculate|i made (a|an) (mistake|error)|correct(ing|ion)|that's wrong|recompute)\b",
        re.I,
    ),
}


def split_sentences(text, max_len=300):
    # split on punctuation or newlines; further chunk very long segments
    parts = re.split(r"(?<=[\.\!\?])\s+|\n+", text)
    out = []
    for p in parts:
        p = p.strip()
        if not p:
            continue
        if len(p) > max_len:
            for i in range(0, len(p), max_len):
                out.append(p[i : i + max_len])
        else:
            out.append(p)
    return out


def label_sentence(sent):
    return {b: bool(pat.search(sent)) for b, pat in BEHAVIOURS.items()}


def count_behaviours(text):
    sents = split_sentences(text)
    counts = {b: 0 for b in BEHAVIOURS}
    for s in sents:
        lab = label_sentence(s)
        for b, v in lab.items():
            if v:
                counts[b] += 1
    return counts, len(sents)


# --- Answer extraction & scoring ---
def extract_answer(text):
    # look at last number in text (post </think> preferred)
    after = text.split("</think>")[-1] if "</think>" in text else text
    nums = re.findall(r"-?\d+", after)
    if nums:
        try:
            return int(nums[-1])
        except:
            return None
    nums = re.findall(r"-?\d+", text)
    if nums:
        try:
            return int(nums[-1])
        except:
            return None
    return None


def score(tasks, gens):
    correct = 0
    for t, g in zip(tasks, gens):
        pred = extract_answer(g)
        if pred is not None and pred == t["answer"]:
            correct += 1
    return correct / len(tasks)


# --- Determine model architecture: use residual stream at a middle layer ---
n_layers = model.config.num_hidden_layers
TARGET_LAYER = n_layers // 2
print(f"Model has {n_layers} layers; using target layer {TARGET_LAYER}")


# Access the transformer layers list
def get_layers():
    return model.model.layers


# --- Generation with optional steering hook and activation capture ---
def build_prompt(question):
    msgs = [
        {
            "role": "user",
            "content": question
            + "\nSolve step by step and give the final numeric answer.",
        }
    ]
    return tokenizer.apply_chat_template(
        msgs, tokenize=False, add_generation_prompt=True
    )


@torch.no_grad()
def generate_with_capture(
    question, capture=False, steer_vec=None, coeff=0.0, max_new_tokens=1024
):
    prompt = build_prompt(question)
    inputs = tokenizer(prompt, return_tensors="pt").to(device)
    prompt_len = inputs["input_ids"].shape[1]

    captured_prompt_act = {}
    hooks = []
    layer = get_layers()[TARGET_LAYER]

    if capture:

        def cap_hook(mod, inp, out):
            h = out[0] if isinstance(out, tuple) else out
            # store mean over prompt tokens on first forward only
            if "act" not in captured_prompt_act:
                # first call has full prompt; take mean of last 32 tokens of the prompt
                a = h[0, -min(32, h.shape[1]) :, :].float().mean(dim=0).cpu()
                captured_prompt_act["act"] = a

        hooks.append(layer.register_forward_hook(cap_hook))

    if steer_vec is not None and coeff != 0.0:
        sv = steer_vec.to(device=device, dtype=next(model.parameters()).dtype)

        def steer_hook(mod, inp, out):
            if isinstance(out, tuple):
                h = out[0]
                h = h + coeff * sv
                return (h,) + out[1:]
            else:
                return out + coeff * sv

        hooks.append(layer.register_forward_hook(steer_hook))

    try:
        gen = model.generate(
            **inputs,
            max_new_tokens=max_new_tokens,
            do_sample=False,
            temperature=1.0,
            pad_token_id=tokenizer.eos_token_id,
        )
    finally:
        for h in hooks:
            h.remove()

    text = tokenizer.decode(gen[0][prompt_len:], skip_special_tokens=True)
    act = captured_prompt_act.get("act", None)
    return text, act


# --- Also need per-sentence activations for behaviour vector extraction ---
# Approach: after baseline generation, take each sentence, re-encode the full [prompt+chain up to that sentence] and grab activation at last token of that sentence, at TARGET_LAYER.


@torch.no_grad()
def activations_for_texts(text_chunks, batch=1):
    """Given list of full-context strings, return mean of last-16-token activations at TARGET_LAYER."""
    acts = []
    layer = get_layers()[TARGET_LAYER]
    cap = {}

    def hook(mod, inp, out):
        h = out[0] if isinstance(out, tuple) else out
        cap["h"] = h.detach()

    hh = layer.register_forward_hook(hook)
    try:
        for s in text_chunks:
            ids = tokenizer(
                s, return_tensors="pt", truncation=True, max_length=2048
            ).to(device)
            if ids["input_ids"].shape[1] < 2:
                acts.append(None)
                continue
            cap.clear()
            model(**ids)
            h = cap["h"]
            a = h[0, -min(16, h.shape[1]) :, :].float().mean(dim=0).cpu()
            acts.append(a)
    finally:
        hh.remove()
    return acts


# --- Stage 1: Baseline generation ---
experiment_data = {
    "r1_distill_llama_8b_steering": {
        "metrics": {"train": [], "val": []},
        "losses": {"train": [], "val": []},
        "predictions": [],
        "ground_truth": [],
        "behaviour_counts": {},
        "baseline_accuracy": None,
        "steered_results": {},
        "success_rate": None,
    }
}
ed = experiment_data["r1_distill_llama_8b_steering"]

BASELINE_TASKS = tasks[:20]  # for extraction
EVAL_TASKS = tasks[20:40]  # for evaluation

print("=== Baseline generation on extraction set ===")
baseline_chains = []
t0 = time.time()
for i, t in enumerate(BASELINE_TASKS):
    text, _ = generate_with_capture(t["question"], max_new_tokens=1024)
    baseline_chains.append(text)
    if i < 2:
        print(f"\n--- Sample baseline chain {i} ---\n{text[:1500]}\n---")
print(f"Baseline extraction gen done in {time.time()-t0:.1f}s")

# --- Stage 2: Collect all (sentence, label) pairs from baseline chains ---
all_examples = []  # list of dicts: {task_idx, sent_idx, sent, labels, context}
for ti, (t, chain) in enumerate(zip(BASELINE_TASKS, baseline_chains)):
    sents = split_sentences(chain)
    running = build_prompt(t["question"])
    for si, s in enumerate(sents):
        running_new = running + s
        labels = label_sentence(s)
        all_examples.append(
            {
                "task_idx": ti,
                "sent_idx": si,
                "sent": s,
                "labels": labels,
                "context": running_new,
            }
        )
        running = running_new + " "

print(f"\nTotal sentences collected: {len(all_examples)}")
per_beh_counts = {b: sum(1 for e in all_examples if e["labels"][b]) for b in BEHAVIOURS}
print("Positive counts per behaviour:", per_beh_counts)
ed["behaviour_counts"] = per_beh_counts

# --- Stage 3: Build balanced pos/neg per behaviour and extract steering vectors ---
MAX_PER_CLASS = 20
steering_vectors = {}
for beh in BEHAVIOURS:
    pos = [e for e in all_examples if e["labels"][beh]]
    neg = [e for e in all_examples if not e["labels"][beh]]
    if len(pos) < 3:
        print(f"[{beh}] too few positives ({len(pos)}) — skipping")
        continue
    random.Random(42).shuffle(neg)
    n_take = min(len(pos), MAX_PER_CLASS)
    pos_s = pos[:n_take]
    neg_s = neg[:n_take]
    print(f"[{beh}] pos={len(pos_s)}, neg={len(neg_s)}")

    pos_acts = activations_for_texts([e["context"] for e in pos_s])
    neg_acts = activations_for_texts([e["context"] for e in neg_s])
    pos_acts = torch.stack([a for a in pos_acts if a is not None])
    neg_acts = torch.stack([a for a in neg_acts if a is not None])
    v = pos_acts.mean(0) - neg_acts.mean(0)
    print(
        f"  vector norm={v.norm().item():.3f}, pos_mean_norm={pos_acts.mean(0).norm().item():.3f}"
    )
    steering_vectors[beh] = v

if not steering_vectors:
    print("No steering vectors extracted — aborting.")
    np.save(os.path.join(working_dir, "experiment_data.npy"), experiment_data)
    raise SystemExit(0)

# --- Stage 4: Evaluate baseline on eval set ---
print("\n=== Baseline generation on eval set ===")
eval_baseline_gens = []
for i, t in enumerate(EVAL_TASKS):
    text, _ = generate_with_capture(t["question"], max_new_tokens=1024)
    eval_baseline_gens.append(text)
baseline_acc = score(EVAL_TASKS, eval_baseline_gens)
baseline_beh_freq = {b: 0.0 for b in BEHAVIOURS}
for g in eval_baseline_gens:
    c, ns = count_behaviours(g)
    for b in BEHAVIOURS:
        baseline_beh_freq[b] += c[b] / max(ns, 1)
for b in BEHAVIOURS:
    baseline_beh_freq[b] /= len(eval_baseline_gens)
print(f"Baseline eval accuracy: {baseline_acc:.3f}")
print(f"Baseline behaviour freq per sentence: {baseline_beh_freq}")
ed["baseline_accuracy"] = baseline_acc

# Diagnostic gate
if baseline_acc < 0.2:
    print(
        f"WARNING: baseline accuracy low ({baseline_acc:.3f}); results may be unreliable but proceeding."
    )

# --- Stage 5: Sweep coefficients per behaviour ---
# Choose coefficient magnitude so that ||coeff * v|| ~ 0.15 * ||h|| (approx activation norm ~ vector norm scale)
COEFFS = [-2.0, -1.0, 0.0, 1.0, 2.0]
steered_results = {}
success_count = 0
total_evaluated = 0

for beh, v in steering_vectors.items():
    # scale so unit magnitude perturbation
    v_unit = v / (v.norm() + 1e-6)
    # target perturbation norm: use fraction of typical activation norm; pick 5.0
    BASE_SCALE = 5.0
    per_coeff = {}
    for c in COEFFS:
        scale = c * BASE_SCALE
        sv = v_unit if scale != 0 else None
        gens = []
        for t in EVAL_TASKS:
            text, _ = generate_with_capture(
                t["question"], steer_vec=sv, coeff=scale, max_new_tokens=1024
            )
            gens.append(text)
        acc = score(EVAL_TASKS, gens)
        beh_freq = 0.0
        for g in gens:
            cnt, ns = count_behaviours(g)
            beh_freq += cnt[beh] / max(ns, 1)
        beh_freq /= len(gens)
        per_coeff[c] = {"accuracy": acc, "beh_freq": beh_freq}
        print(
            f"[{beh}] coeff={c:+.1f} scale={scale:+.2f}  acc={acc:.3f}  {beh}_freq={beh_freq:.4f}"
        )

    # Success criteria: freq(+) > freq(0) AND freq(-) < freq(0), and acc(+),acc(-) within 0.10 of baseline
    f_pos = per_coeff[1.0]["beh_freq"]
    f_neg = per_coeff[-1.0]["beh_freq"]
    f_0 = per_coeff[0.0]["beh_freq"]
    a_pos = per_coeff[1.0]["accuracy"]
    a_neg = per_coeff[-1.0]["accuracy"]
    dir_ok = (f_pos > f_0 + 1e-4) and (
        f_neg < f_0 - 1e-4 or f_0 == 0.0 and f_neg <= f_0
    )
    acc_ok = abs(a_pos - baseline_acc) <= 0.10 and abs(a_neg - baseline_acc) <= 0.10
    success = bool(dir_ok and acc_ok)
    per_coeff["success"] = success
    per_coeff["dir_ok"] = bool(dir_ok)
    per_coeff["acc_ok"] = bool(acc_ok)
    steered_results[beh] = per_coeff
    total_evaluated += 1
    if success:
        success_count += 1
    print(f"[{beh}] success={success} (dir_ok={dir_ok}, acc_ok={acc_ok})")

    # log as validation loss surrogate per epoch (per behaviour)
    ed["metrics"]["val"].append({"behaviour": beh, "result": per_coeff})
    print(f"Epoch {total_evaluated}: validation_loss = {1.0 - float(success):.4f}")

success_rate = success_count / max(total_evaluated, 1)
print(
    f"\n=== behaviour_steering_success_rate = {success_rate:.3f} ({success_count}/{total_evaluated}) ==="
)
ed["steered_results"] = steered_results
ed["success_rate"] = success_rate

np.save(os.path.join(working_dir, "experiment_data.npy"), experiment_data)
with open(os.path.join(working_dir, "summary.json"), "w") as f:
    json.dump(
        {
            "baseline_accuracy": baseline_acc,
            "baseline_behaviour_freq": baseline_beh_freq,
            "behaviour_counts": per_beh_counts,
            "steered_results": {
                k: {str(kk): vv for kk, vv in v.items()}
                for k, v in steered_results.items()
            },
            "success_rate": success_rate,
            "target_layer": TARGET_LAYER,
            "n_layers": n_layers,
        },
        f,
        indent=2,
        default=str,
    )

print("Done. Saved to", working_dir)

