import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
data_path = os.path.join(working_dir, "experiment_data.npy")

experiment_data = np.load(data_path, allow_pickle=True).item()

for dataset_name, ed in experiment_data.items():
    print(f"\n===== Dataset: {dataset_name} =====")

    baseline_acc = ed.get("baseline_accuracy", None)
    if baseline_acc is not None:
        print(f"Baseline evaluation accuracy: {baseline_acc:.4f}")

    success_rate = ed.get("success_rate", None)
    if success_rate is not None:
        print(f"Behaviour steering success rate: {success_rate:.4f}")

    behaviour_counts = ed.get("behaviour_counts", {})
    if behaviour_counts:
        print("\n-- Behaviour positive sentence counts (extraction set) --")
        for beh, cnt in behaviour_counts.items():
            print(f"  {beh} positive sentence count: {cnt}")

    steered_results = ed.get("steered_results", {})
    if steered_results:
        print("\n-- Steered results per behaviour --")
        for beh, per_coeff in steered_results.items():
            print(f"\nBehaviour: {beh}")
            coeff_entries = {
                k: v
                for k, v in per_coeff.items()
                if isinstance(k, (int, float)) and isinstance(v, dict)
            }

            if coeff_entries:
                best_acc_coeff = max(
                    coeff_entries.keys(), key=lambda k: coeff_entries[k]["accuracy"]
                )
                best_acc_val = coeff_entries[best_acc_coeff]["accuracy"]
                print(
                    f"  Best steered accuracy: {best_acc_val:.4f} (at coeff={best_acc_coeff:+.1f})"
                )

                max_freq_coeff = max(
                    coeff_entries.keys(), key=lambda k: coeff_entries[k]["beh_freq"]
                )
                max_freq_val = coeff_entries[max_freq_coeff]["beh_freq"]
                print(
                    f"  Max behaviour frequency: {max_freq_val:.4f} (at coeff={max_freq_coeff:+.1f})"
                )

                min_freq_coeff = min(
                    coeff_entries.keys(), key=lambda k: coeff_entries[k]["beh_freq"]
                )
                min_freq_val = coeff_entries[min_freq_coeff]["beh_freq"]
                print(
                    f"  Min behaviour frequency: {min_freq_val:.4f} (at coeff={min_freq_coeff:+.1f})"
                )

                if 0.0 in coeff_entries:
                    print(
                        f"  Zero-coeff (control) accuracy: {coeff_entries[0.0]['accuracy']:.4f}"
                    )
                    print(
                        f"  Zero-coeff (control) behaviour frequency: {coeff_entries[0.0]['beh_freq']:.4f}"
                    )
                if 1.0 in coeff_entries:
                    print(
                        f"  Positive-coeff (+1.0) accuracy: {coeff_entries[1.0]['accuracy']:.4f}"
                    )
                    print(
                        f"  Positive-coeff (+1.0) behaviour frequency: {coeff_entries[1.0]['beh_freq']:.4f}"
                    )
                if -1.0 in coeff_entries:
                    print(
                        f"  Negative-coeff (-1.0) accuracy: {coeff_entries[-1.0]['accuracy']:.4f}"
                    )
                    print(
                        f"  Negative-coeff (-1.0) behaviour frequency: {coeff_entries[-1.0]['beh_freq']:.4f}"
                    )

            if "success" in per_coeff:
                print(f"  Steering success flag: {per_coeff['success']}")
            if "dir_ok" in per_coeff:
                print(f"  Direction criterion satisfied: {per_coeff['dir_ok']}")
            if "acc_ok" in per_coeff:
                print(
                    f"  Accuracy preservation criterion satisfied: {per_coeff['acc_ok']}"
                )
